(()=>{if(!document.getElementById('M30-lab'))return;const zh=document.documentElement.lang.startsWith('zh'),el=k=>document.getElementById('M30-'+k),y=[0,0,0,1,0,1,1,1,1,0];let p={split:5,criterion:'gini'},s={};const impurity=a=>{let q=a.reduce((a,b)=>a+b,0)/a.length;return p.criterion==='gini'?2*q*(1-q):(q===0||q===1?0:-q*Math.log2(q)-(1-q)*Math.log2(1-q));};function gain(k){const value=impurity(y)-k/10*impurity(y.slice(0,k))-(10-k)/10*impurity(y.slice(k));return Math.abs(value)<1e-14?0:value;}
function render(){let left=y.slice(0,p.split),right=y.slice(p.split);s={...p,gain:gain(p.split),parent_impurity:impurity(y),left_impurity:impurity(left),right_impurity:impurity(right),left_positive:left.reduce((a,b)=>a+b,0),right_positive:right.reduce((a,b)=>a+b,0)};let svg='<rect x="45" y="40" width="800" height="125" fill="#f4f8f9"/>';y.forEach((v,i)=>svg+=`<circle cx="${85+76*i}" cy="90" r="18" fill="${v?'#d48745':'#167d87'}"/><text x="${85+76*i}" y="96" fill="white" text-anchor="middle">${v}</text><text x="${85+76*i}" y="145" text-anchor="middle">${i+1}</text>`);let xx=47+76*p.split;svg+=`<path d="M${xx} 25V165" stroke="#443556" stroke-width="3" stroke-dasharray="6 5"/><text x="45" y="195">${zh?'左节点':'Left child'}: n=${left.length}, p(1)=${(s.left_positive/left.length).toFixed(3)}</text><text x="455" y="195">${zh?'右节点':'Right child'}: n=${right.length}, p(1)=${(s.right_positive/right.length).toFixed(3)}</text>`;let gains=Array.from({length:9},(_,i)=>gain(i+1)),max=Math.max(...gains,.01);svg+='<path d="M65 250V420H840" stroke="#91a8b4" fill="none"/>';gains.forEach((v,i)=>{let h=v/max*150;svg+=`<rect x="${85+i*80}" y="${420-h}" width="45" height="${h}" fill="${i+1===p.split?'#d48745':'#167d87'}"/><text x="${107+i*80}" y="${410-h}" text-anchor="middle" font-size="13">${v.toFixed(3)}</text><text x="${107+i*80}" y="442" text-anchor="middle">${i+1+.5}</text>`;});svg+=`<text x="65" y="235">${zh?'不纯度改善':'Impurity gain'} (${p.criterion==='gini'?(zh?'无量纲':'unitless'):'bit'})</text><text x="455" y="468" text-anchor="middle">${zh?'候选特征阈值':'Candidate feature threshold'}</text>`;el('plot').innerHTML=svg;el('result').textContent=(zh?'父节点 → 加权子节点 → 改善':'Parent → weighted children → gain')+`: ${s.parent_impurity.toFixed(4)} → ${(s.parent_impurity-s.gain).toFixed(4)} → ${s.gain.toFixed(4)}.`;el('cut').value=p.split;el('cut-value').value=p.split;el('criterion').value=p.criterion;}
function set(q){if(q.split!=null)p.split=Math.max(1,Math.min(9,Math.round(q.split)));if(['gini','entropy'].includes(q.criterion))p.criterion=q.criterion;render();return{...s};}el('cut').addEventListener('input',()=>set({split:+el('cut').value}));el('criterion').addEventListener('change',()=>set({criterion:el('criterion').value}));el('reset').addEventListener('click',()=>{p={split:5,criterion:'gini'};render();});window.CourseLab={set,state:()=>({...s}),reset:()=>{p={split:5,criterion:'gini'};render();return{...s};}};render();})();
